// ─── File: api/Account.java ───
// Sealed interface in the `api` package. It PERMITS subtypes that live in the
// `products` package — allowed because both packages are in the SAME module.
package com.bank.accounts.api;

import com.bank.accounts.products.SavingsAccount;
import com.bank.accounts.products.CurrentAccount;
import com.bank.accounts.products.LoanAccount;
import java.math.BigDecimal;

public sealed interface Account
        permits SavingsAccount, CurrentAccount, LoanAccount {
    String id();
    String holder();
    BigDecimal balance();
}
