// DIFFERENT package from Account, SAME module → permitted. FINAL leaf.
package com.bank.accounts.products;

import com.bank.accounts.api.Account;
import java.math.BigDecimal;

public final class SavingsAccount implements Account {
    private final String id; private final String holder; private final BigDecimal balance;
    public SavingsAccount(String id, String holder, BigDecimal balance) {
        this.id = id; this.holder = holder; this.balance = balance;
    }
    public String id() { return id; }
    public String holder() { return holder; }
    public BigDecimal balance() { return balance; }
}
