// ─── File: CrossPackageDemo.java ───
package com.bank.accounts;

import com.bank.accounts.api.Account;
import com.bank.accounts.products.*;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.*;

public class CrossPackageDemo {
    private static final Logger log = Logger.getLogger(CrossPackageDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Cross-package subtypes work because all are in module com.bank.accounts.
        List<Account> accounts = List.of(
            new SavingsAccount("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")),
            new CurrentAccount("CUR3001", "Priya Sharma", new BigDecimal("250000")),
            new LoanAccount("LN5001", "Rajesh Kumar", new BigDecimal("3000000")));

        for (Account a : accounts) {
            log.info(() -> a.getClass().getSimpleName() + " " + a.id()
                    + " holder=" + a.holder() + " balance=Rs." + a.balance());
        }

        // NOTE (classpath rule): if this code ran on the plain classpath (no module),
        // the permits of a subtype in package products would NOT compile — all
        // permitted subtypes would have to be in package api (same package as Account).

        // NOTE (cross-module rule): a subtype from a DIFFERENT module can NEVER be
        // permitted — a sealed hierarchy cannot span modules. This protects the
        // bank's closed product set from outside additions.
        log.info(() -> "Sealed cross-package demo complete (single module, multiple packages)");
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override public String format(java.util.logging.LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
